const CopyRow = ({ label, value, accent }) => {
    const { addToast } = useToast();
    const [copied, setCopied] = useState(false);

    const handleCopy = () => {
        navigator.clipboard.writeText(value).then(() => {
            setCopied(true);
            addToast(`${label} copied!`, 'success');
            setTimeout(() => setCopied(false), 2000);
        });
    };

    return (
        <div className="flex items-center justify-between p-3.5 bg-white/5 rounded-xl group">
            <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-white/40 mb-0.5">{label}</p>
                <p className="text-sm font-black text-white tracking-wider">{value}</p>
            </div>
            <button
                onClick={handleCopy}
                className={cn(
                    "shrink-0 ml-3 w-8 h-8 rounded-lg flex items-center justify-center transition-all duration-300",
                    copied
                        ? `bg-emerald-500/20 text-emerald-400`
                        : `bg-white/5 text-white/40 hover:bg-white/10 hover:text-white`
                )}
            >
                <Icon name={copied ? 'Check' : 'Copy'} size={14} />
            </button>
        </div>
    );
};

